import{_ as s,o as e,c as n,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"Breaking Down Video LLM Benchmarks: Knowledge, Spatial Perception, or True Temporal Understanding?","description":"","frontmatter":{"title":"Breaking Down Video LLM Benchmarks: Knowledge, Spatial Perception, or True Temporal Understanding?","arxiv":"2505.14321","date":"2025-05-20","authors":"Bo Feng, Zhengfeng Lai, Shiyu Li, Zizhen Wang, Simon Wang, Ping Huang, Meng Cao","categories":"cs.CV","topics":"长视频理解, 基准诊断, 时序推理","outline":[2,2]},"headers":[],"relativePath":"papers/2505.14321.md","filePath":"papers/2505.14321.md","lastUpdated":null}'),r={name:"papers/2505.14321.md"};function p(l,a,o,i,m,c){return e(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="breaking-down-video-llm-benchmarks-knowledge-spatial-perception-or-true-temporal-understanding" tabindex="-1">Breaking Down Video LLM Benchmarks: Knowledge, Spatial Perception, or True Temporal Understanding? <a class="header-anchor" href="#breaking-down-video-llm-benchmarks-knowledge-spatial-perception-or-true-temporal-understanding" aria-label="Permalink to &quot;Breaking Down Video LLM Benchmarks: Knowledge, Spatial Perception, or True Temporal Understanding?&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2505.14321" target="_blank" rel="noreferrer">2505.14321</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-05-20</td></tr><tr><td><strong>作者</strong></td><td>Bo Feng, Zhengfeng Lai, Shiyu Li, Zizhen Wang, Simon Wang, Ping Huang, Meng Cao</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用两道自动化闸门（不给视频能不能答对、把帧打乱后还能不能答对）把任意 VideoQA 基准的题目切成 LLM-Answerable / Semantic / Temporal / Others 四类，再按类别分别报分，从而看清一个总分里到底有多少来自语言先验、多少来自静态画面、多少来自真正的时序。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/long-video-understanding">长视频理解</a></p></blockquote><p>本页依据 <code>arxiv.org/html/2505.14321v1</code> 全文撰写。</p><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视频理解基准的报分方式是一个总数。VideoMME 上 68.2、MLVU 上 74.2，读者默认这些数字度量的是&quot;模型看懂了视频里发生的事&quot;。但视频这个模态相对图像的唯一增量是时间：同样的一组画面，顺序不同，事件就不同。如果一个总分里绝大部分题目跟顺序无关，那这个总分度量的其实是图像理解加语言常识，跟视频没什么关系。</p><p>作者把这件事拆成两个可操作的检验。第一，不给视频，只把题干和选项喂给模型，看它能答对多少；第二，把抽出来的帧随机打乱再喂进去，看分数掉多少。这两个检验都不需要新标注，成本只是多跑两遍推理。全文的核心工作就是把这两个检验固化成一条流水线（VBenchComp），套到七个常用基准上，然后把每个基准的题目组成公布出来。</p><p>这件事的实际价值有两层。一层是评测诚实：知道某个基准里有三成题目不看视频就能答对，就不会再把该基准的提升当成视频能力的提升。另一层是算力。论文表 1 给了在 A100 上评一遍各基准所需的 GPU 小时（评测对象是 Qwen2-VL）：七个基准共 32396 题，2B 模型合计 190.6 小时，7B 213.7 小时，72B 491.9 小时；其中 PerceptionTest 一家就占了 118.1 / 131.2 / 296.3 小时。如果一半题目是冗余的，砍掉它们能省下的是几百 GPU 小时。这个表把&quot;评测本身很贵&quot;变成了一个有数字的论据，而且它老老实实写了硬件型号，这在效率类论述里不常见。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>长视频基准</strong>这条线（LongVideoBench、EgoSchema、NExT-QA、VideoMME、MLVU、LVBench、PerceptionTest）各自强调不同侧面，覆盖面确实在扩大。作者在相关工作里承认，已有研究早就指出这类数据集常常只需要少数几个关键帧就能作答，这削弱了它们评估真实时序推理的效力。问题在于这条观察此前停留在定性层面，没有变成一个可以逐题打标签、可以在任何基准上重跑的协议。</p><p><strong>图像 QA 里的 answer leakage 研究</strong>已经把&quot;不看图也能答&quot;这件事做实了，作者明确说自己的 LLM-Answerable 判据受此启发。图像侧的经验没有被直接搬到视频侧，一个现实原因是视频推理贵：要判定一道题是否 LLM-Answerable，需要额外跑一遍纯文本推理；要判定它是否依赖顺序，还需要再跑两遍打乱版本。三倍的评测开销在长视频上不是小事，表 1 的 GPU 小时正好解释了这条路为什么长期没人走。</p><p><strong>模型侧的时序建模工作</strong>（论文提到 VideoLLaMB 在 bridge layer 里加 memory token、InternVideo2.5 用密集视觉任务标注加层次化 token 压缩）都在往&quot;更好地捕捉动态&quot;的方向推，但它们的效果只能通过总分来验证。如果总分本身混着三类题，这些改进到底改进了什么就没法归因。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从一个可以直接动手的疑问开始：如果不给视频，模型能答对多少？这一步不需要任何新概念，图像侧已经有现成做法。跑完之后拿到的数字足够触目：GPT-4o 在 VideoMME 与 NExT-QA 上不看视频最高能到 50% 准确率；开源的 PLLaVA-34B 在 VideoMME 上不看视频也有 37.0%；在 LongVideoBench 这种长视频基准上，这些模型不喂真实长视频也能超过 35%。</p><p>拿到这个结果，下一个问题自然是：剩下那些确实需要看视频的题，是不是需要看&quot;顺序&quot;？最省事的扰动是打乱帧。作者在四类模型上做了这件事——闭源的 GPT-4o 与 Gemini-1.5-Pro、免训练的 SlowFast-LLaVA、LoRA 微调的 PLLaVA、视频 SFT 的 LLaVA-OneVision——发现分数几乎不动，而且模型规模从 7B 到 72B 都是这个样子。更尴尬的是，有时候打乱之后分数还会上升：Gemini-1.5-Pro 在 EgoSchema 上、GPT-4o 在 NExT-QA 上都出现了这种情况。</p><p>两个扰动各自把题目切掉一刀，把它们串起来就是一棵判定树，这棵树就是方法本身。至于用谁来当判定器，作者选了当时最强的两个闭源模型并要求两者一致，理由是判据越保守，被误标成&quot;简单题&quot;的比例越低。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>一个视频基准的总分是三种能力的混合物，而这三种能力可以用两个不需要标注的扰动分离开：抽掉视频，考的就是语言先验；打乱帧序，考的就是静态语义。剩下那些&quot;原序能答、乱序答不对&quot;的题，才是这个基准真正在测时间的部分。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>流水线以 GPT-4o 与 Gemini-1.5-Pro 两个模型作为判定器，逐题走四步。</p><p><strong>第一步，LLM-Answerable。</strong> 只给题干与选项，不给视频。若两个判定器都答对，该题标为 LLM-Answerable，占比记为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span>。作者把这类题分成两种来源：题干本身信息就够（text-answerable），以及模型训练时见过原题（memorized）。</p><p><strong>第二步，Semantic。</strong> 对剩余题目，先用原序帧让两个判定器作答，再把抽出的帧随机打乱，重复两次，再让它们作答。若两个模型在打乱前后都答对，该题标为 Semantic，占比记为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span>。判据的含义是：单帧或某一组静态帧的信息已经足够回答。</p><p><strong>第三步，Temporal。</strong> 若 GPT-4o 或 Gemini-1.5-Pro 在原序下答对、在打乱后答错，该题标为 Temporal，占比记为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span></span></span></span>。</p><p><strong>第四步，Others。</strong> 其余全部归入 Others，占比 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span></span></span></span>。作者说明这一类混着两种东西：所有 SOTA 模型都答不对的难题，以及需要音频等其它模态才能作答的题（例如 VideoMME 里依赖对白、环境音、语气的题）。</p><p><strong>一个具体例子</strong>：VideoMME 里问&quot;视频结尾时厨师把锅端到了哪里&quot;。若不给视频、只看选项，GPT-4o 与 Gemini 都能靠常识猜中，它就是 LLM-Answerable；若必须看到画面里的灶台与餐桌但打乱帧后仍能答对，它是 Semantic；若把帧打乱后模型就分不清&quot;端上桌&quot;和&quot;端下灶&quot;哪个在后，它才是 Temporal。</p><p><strong>输出</strong>：一个基准的四元组 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span><span class="mclose">)</span></span></span></span>，以及只保留 Semantic 与 Temporal 两类题重新计算的 VBenchComp Score。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文没有需要推导的形式化数学，四个比例只是计数除以总数：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.</span></span></span></span></span></p><p>值得说明的是判据的非对称性。LLM-Answerable 与 Semantic 要求<strong>两个</strong>判定器都答对（AND），而 Temporal 只要求<strong>其中一个</strong>在原序对、乱序错（OR）。AND 使得前两类偏保守：一道题只有在两个强模型都能&quot;作弊&quot;成功时才被判为可绕过。OR 使得 Temporal 偏宽松：只要有一个模型对帧序敏感就算。这个选择的效果是把不确定的题往 Others 推，因此 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span></span></span></span> 天然偏大（七个基准里有四个的 Others 超过 25%），而 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span></span></span></span> 是一个下界估计而非精确值。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>第一个问题：现有基准到底是由什么构成的。</strong> 表 2 给出七个基准的四类计数与占比。LLM-Answerable 一列：NExT-QA 34.79%（1738/4996）、VideoMME 31.15%（841/2700）、MLVU 28.57%（621/2174）、LongVideoBench 27.15%（363/1337）、EgoSchema 26.60%（133/500）、PerceptionTest 19.03%（3642/19140）、LVBench 9.04%（140/1549）。Semantic 一列除 LongVideoBench（23.03%）与 LVBench（20.72%）外全部超过 30%，NExT-QA 高达 37.63%。真正的 Temporal 一列则普遍很低：NExT-QA 8.75%、EgoSchema 9.00%、VideoMME 13.74%、MLVU 17.62%、LongVideoBench 17.58%、PerceptionTest 16.29%，只有 LVBench 达到 22.92%。也就是说，这些基准里&quot;必须看顺序&quot;的题大多不到两成。</p><p><strong>第二个问题：分类之后模型排序会不会变。</strong> 表 3 在六个基准上给了 7B 与 72B 两档的分类得分（除 VideoMME-long 用 128 帧外均为 64 帧）。EgoSchema 上 Qwen2-VL-7B 总分 65.8 略高于 LLaVA-Video-7B 的 61.8，但拆开看，Qwen2-VL 的 LLM 一列是 85.0 对 72.2，Semantic 两者都是 83.5，Temporal 一列 Qwen2-VL 反而只有 37.8 而 LLaVA-Video 是 46.7。作者据此判断 Qwen2-VL-7B 的总分优势主要来自更强的语言 backbone。VideoMME 上结论翻转：LLaVA-Video-7B 的 Semantic 82.0 对 78.4、Temporal 42.6 对 36.7，两个视觉相关维度都更高。同一对模型在两个基准上的相对优劣来源完全不同，这是总分看不出来的。</p><p><strong>第三个问题：能不能砍题省钱。</strong> 只保留 Semantic 与 Temporal 计算 VBenchComp Score，按表 2 大约砍掉一半题目，作者报告模型排序与原始总分高度一致（图 5，以散点与趋势线呈现，正文未给相关系数数值）。作者由此主张 Semantic 加 Temporal 已经足以保留基准的区分度。</p><p><strong>局限（作者自陈）</strong>：分类流水线重度依赖 GPT-4o 与 Gemini，可能引入偏差；精简子集可能漏掉边缘样本；框架只覆盖 QA，未延伸到 captioning、retrieval、grounding。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句版</strong>：视频基准的总分把语言先验、静态语义、时序推理三件事混在一起报。用&quot;不给视频&quot;和&quot;打乱帧序&quot;两个零标注扰动就能把它们分开，成本是多跑两到三遍推理。七个常用基准里 LLM-Answerable 普遍占两到三成（NExT-QA 34.79%），Semantic 多数超过 30%，真正的 Temporal 大多不到 20%。分类之后模型的相对优劣会改写：EgoSchema 上 Qwen2-VL-7B 的总分优势来自 LLM 一列（85.0 对 72.2），Temporal 一列反而落后（37.8 对 46.7）。只保留 Semantic 与 Temporal 能砍掉约一半题目而保持排序，这在评一遍要几百 A100 小时的场景下是实打实的收益。</p><p><strong>3 句版</strong>：VBenchComp 用两道自动闸门把 VideoQA 题目切成四类并逐类报分。七个基准里真正需要帧序的题普遍不到两成，两三成不看视频就能答对。分类报分会改变模型的优劣归因，总分做不到这件事。</p><p><strong>1 句版</strong>：在发布一个视频基准之前，先跑一遍纯文本推理和一遍打乱帧推理，把能被绕过的题标出来。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要命的一条是：<strong>&quot;打乱帧后仍答对&quot;等价于&quot;这道题不需要时序&quot;</strong>。整个分类的第二、第三步都建立在这个等价上，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span> 和 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span></span></span></span> 的全部含义都由它承载。</p><p>它在实践中会以一个可预测的方式失效。打乱帧序破坏的是全局顺序，但不破坏局部共现：一段&quot;倒水—杯子满—端起来&quot;的视频，打乱后每一帧仍然带着自己的语义，模型完全可以从&quot;有一帧杯子空、有一帧杯子满&quot;推出&quot;先空后满&quot;，因为它知道杯子不会自己变空。也就是说，模型可以用<strong>世界常识重建顺序</strong>，从而在打乱后照样答对，而这道题在人看来明明是时序题。按本文的判据，它会被判成 Semantic。这个方向的误判会系统性地压低 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span></span></span></span>、抬高 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span>。</p><p>反过来的失效模式也存在：打乱帧会让输入分布偏离训练分布，模型可能仅仅因为输入变得奇怪而答错，而不是因为丢失了顺序信息。这会把非时序题误判成 Temporal，方向相反。论文的 OR 判据（只要一个模型原序对乱序错即可）放大了这个方向的风险。</p><p>论文为这条假设提供的证据是间接的：它展示了打乱后分数几乎不变这一现象（图 3），但没有做人工标注来校验&quot;被判为 Semantic 的题在人看来是否真的不需要顺序&quot;。这属于缺失证据。参照后来的工作（TempCore，arXiv:2509.01167）确实用人工时序评分校验了类似的自动判据并报告了相关系数，说明这项校验是可做的，本文没有做。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要复现七个基准。取 VideoMME 的 300 道题即可，一周内可完成：</p><ol><li>用一个开源判定器对（例如 Qwen2.5-VL-7B 与 InternVL 系列各一个）替代 GPT-4o 与 Gemini，按 §5 的四步跑出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span><span class="mclose">)</span></span></span></span>。</li><li>找 3 位标注者对同样 300 题独立打&quot;这道题是否必须知道帧的先后顺序&quot;的二值标签，计算标注者一致性。</li><li>把自动标签与人工标签做混淆矩阵，重点看被判为 Semantic 的题里有多少被人标为需要顺序。</li><li>判据：若 Semantic 类中人工判定&quot;需要顺序&quot;的比例低于 15%，本文的核心假设在这一批数据上成立；若超过 30%，则 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span></span></span></span> 是严重低估，表 2 里&quot;真正时序题不到两成&quot;的结论需要下修。</li><li>附加对照：把判定器换成两个更弱的开源模型重跑一遍，看四类占比漂移多少。若漂移超过 5 个百分点，说明这套占比是判定器的属性而不是基准的属性。</li></ol><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最强的攻击针对 §9 里那条常识重建通路，构造方式是<strong>保证顺序不可从单帧集合推出</strong>。做法：拍或剪一批可逆事件的短片——开门与关门、把书从架上取下与放回、把水从 A 杯倒进 B 杯与从 B 倒回 A。这类事件的正序与倒序在帧集合上完全同分布，任何常识先验都无法判断哪个在前。在这批数据上重跑本文的流水线：如果 Semantic 的占比相比原基准急剧下降、Temporal 急剧上升，就证明原基准里高达三成以上的 Semantic 主要是常识可重建的题，本文报告的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span></span></span></span> 是判据本身造成的，而不是基准的固有属性。</p><p>第二重攻击针对表 2 与表 3 的口径。表 2 报告的是&quot;两个闭源判定器&quot;对每道题的分类，表 3 报告的却是<strong>另外六个开源模型</strong>在这套分类上的得分。分类器与被评者不是同一批模型，这本身是好设计，但它意味着表 3 里 Temporal 一列的低分有一个替代解释：这些题之所以被标成 Temporal，正是因为 GPT-4o 或 Gemini 在乱序下答错，而这个筛选天然挑出了对扰动敏感、也就是更难的题。要排除这个解释，需要一个对照：随机抽取同样数量的题构成一个难度匹配的对照集，看开源模型在其上的得分是否同样低。论文没有做这个对照。</p><p>第三点，本文报告的所有分数都没有置信区间。EgoSchema 只有 500 题，切成四类后 Temporal 一类只剩 45 题；表 3(a) 中 Temporal 一列 37.8 与 46.7 的差距建立在这 45 题上，二项抽样的标准误约 7 个百分点，两者的区间大概率重叠。用它支撑&quot;Qwen2-VL-7B 时序更弱&quot;这一论断，证据强度不足。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>驱动这个 idea 的局限是判据的粗糙：本文只有一个扰动算子（随机打乱），而&quot;时序&quot;至少包含顺序、时长、速率、因果方向四种依赖，随机打乱只能探到第一种。TempCore 后来指出 FSS 同样只覆盖&quot;依赖哪些帧&quot;这一个侧面，也是同一个问题的另一个表现。</p><p>值得借鉴的相邻工具来自因果推断里的<strong>干预谱</strong>：不是用单一扰动做二分类，而是设计一族参数化干预算子，每个算子只破坏一种时间属性，然后把一道题在整族算子下的准确率跌幅向量当作它的&quot;时序指纹&quot;。具体可用四个算子：随机置换（破坏顺序）、整体倒放（破坏因果方向但保留顺序结构）、抽帧稀疏化（破坏时长与速率）、局部段内置换（只破坏细粒度顺序，保留粗粒度）。一道题的指纹是四维向量，基准的组成就从四个标量升级成一张指纹分布图。</p><p>第一个实验不需要新基准：在 VideoMME 上对每道题跑这四个算子各三次，得到 2700×4 的跌幅矩阵，对它做聚类。若聚类结果与本文的四分类高度重合，说明单一扰动已经够用，本文的结论稳固；若出现明显的新簇（例如&quot;对倒放极敏感但对置换不敏感&quot;的一群题），就说明现有的 shuffle-invariance 判据把不同的时序能力压成了同一个标签，而这些簇正是下一代基准应该单独报分的维度。</p>',55)])])}const d=s(r,[["render",p]]);export{g as __pageData,d as default};
